<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Survey</title><style>body{background:#f6f8fc;font:15px Arial;color:#202124;margin:0}.wrap{max-width:900px;margin:35px auto}.card{background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:24px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 210px;gap:16px}input,select,textarea{box-sizing:border-box;width:100%;padding:10px;border:1px solid #bbb;border-radius:4px;font:inherit}textarea{resize:vertical}.hint{color:#5f6368;font-size:13px}.button{background:#673ab7;color:white;border:0;padding:10px 18px;border-radius:4px;font-weight:bold;cursor:pointer}.delete{color:#c5221f;text-decoration:none;float:right}.message{padding:12px;border-radius:4px;margin-bottom:15px}.ok{background:#e6f4ea;color:#137333}.err{background:#fce8e6;color:#c5221f}table{border-collapse:collapse;width:100%}th,td{padding:12px;text-align:left;border-bottom:1px solid #ddd}th{color:#5f6368;font-size:12px;text-transform:uppercase}@media(max-width:600px){.wrap{margin:15px}.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Kelola Survey</h1><p><?= html_escape($survey->title) ?> · <strong><?= $responses ?></strong> tanggapan</p><?php if($this->session->flashdata('success')): ?><div class="message ok"><?= $this->session->flashdata('success') ?></div><?php endif; ?><?php if($this->session->flashdata('error')): ?><div class="message err"><?= $this->session->flashdata('error') ?></div><?php endif; ?><section class="card"><h2>Tambah pertanyaan</h2><?= form_open('survey/add_question') ?><p><label>Pertanyaan<br><input required name="question_text" placeholder="Contoh: Seberapa puas Anda?" /></label></p><div class="grid"><p><label>Tipe jawaban<br><select name="question_type"><option value="text">Jawaban singkat</option><option value="textarea">Paragraf</option><option value="radio">Pilihan ganda</option><option value="checkbox">Kotak centang</option><option value="select">Daftar pilihan</option></select></label></p><p><label>&nbsp;<br><input type="checkbox" name="is_required" value="1" style="width:auto"> Wajib diisi</label></p></div><p><label>Pilihan jawaban (satu pilihan per baris)<br><textarea name="options" rows="4" placeholder="Sangat puas&#10;Puas&#10;Cukup puas"></textarea></label><span class="hint">Isi hanya untuk pilihan ganda, kotak centang, atau daftar pilihan.</span></p><button class="button" type="submit">Tambah pertanyaan</button><?= form_close() ?></section><section class="card"><h2>Daftar pertanyaan</h2><?php if(empty($questions)): ?><p class="hint">Belum ada pertanyaan. Tambahkan pertanyaan pertama di atas.</p><?php else: ?><table><thead><tr><th>#</th><th>Pertanyaan</th><th>Tipe</th><th></th></tr></thead><tbody><?php foreach($questions as $i => $q): ?><tr><td><?= $i+1 ?></td><td><?= html_escape($q->question_text) ?><?= $q->is_required ? ' <span style="color:#c5221f">*</span>' : '' ?></td><td><?= html_escape($q->question_type) ?></td><td><a class="delete" onclick="return confirm('Hapus pertanyaan ini?')" href="<?= site_url('survey/delete_question/'.$q->id) ?>">Hapus</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><p><a href="<?= site_url('survey') ?>" target="_blank">Buka form publik ↗</a></p></main></body></html>
